#!/usr/bin/env node
// Bundle ext/proj/src/ into ext/proj/index.js via @gcu/build — proj4js (vendored verbatim in
// src/vendor-proj4.js) + the EPSG table + the world outline, one self-contained ESM.
// The data and the vendored file are generated by ext/proj/tools/*.mjs (see README).
import { bundle } from '../build/src/main.js';

const r = await bundle({ at: import.meta.url, sourcemap: false, meta: false, lint: false });   // lint off: the vendored proj4 bundle is minified ES5 (var)
console.log(`Built ext/proj/index.js (${(r.code.length / 1024).toFixed(1)} KB, ${r.meta.exports.length} exports)`);
